#!/usr/bin/env python3
"""Underline all headlines in quarterly_report.docx.

Headlines are the all-caps section title paragraphs (no pStyle in this doc).
Direct edit (no tracked changes) since this is a straightforward formatting
request on the user's own report.
"""
import os
import re
import shutil
import zipfile
import xml.dom.minidom as minidom

SRC = "quarterly_report.docx"
UNPACKED = "unpacked"
DOC_REL = os.path.join("word", "document.xml")


def para_text(p):
    """Concatenated w:t text of a paragraph."""
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild and t.firstChild.nodeType == t.firstChild.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(p):
    text = para_text(p).strip()
    if not text:
        return False
    if not any(ch.isalpha() for ch in text):
        return False
    return text == text.upper()


def add_underline_to_runs(p):
    """Add <w:u w:val='single'/> to each direct run child's rPr."""
    count = 0
    for child in p.childNodes:
        if child.nodeType != child.ELEMENT_NODE or child.tagName != "w:r":
            continue
        rpr = None
        for c in child.childNodes:
            if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:rPr":
                rpr = c
                break
        if rpr is None:
            rpr = child.ownerDocument.createElement("w:rPr")
            child.insertBefore(rpr, child.firstChild)
        # Skip if already underlined
        if any(c.nodeType == c.ELEMENT_NODE and c.tagName == "w:u" for c in rpr.childNodes):
            continue
        u = child.ownerDocument.createElement("w:u")
        u.setAttribute("w:val", "single")
        # Insert after w:sz-cs/w:sz/w:rFonts for schema-correct ordering
        anchor = None
        for tag in ("w:sz-cs", "w:sz", "w:rFonts"):
            for c in rpr.childNodes:
                if c.nodeType == c.ELEMENT_NODE and c.tagName == tag:
                    anchor = c
        if anchor is not None:
            rpr.insertBefore(u, anchor.nextSibling)
        else:
            rpr.appendChild(u)
        count += 1
    return count


def main():
    doc_path = os.path.join(UNPACKED, DOC_REL)

    with open(doc_path, "r", encoding="utf-8") as f:
        raw = f.read()
    m = re.match(r"<\?xml[^>]*\?>", raw)
    decl = m.group(0) if m else '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'

    dom = minidom.parse(doc_path)
    paras = dom.getElementsByTagName("w:p")

    underlined = []
    for p in paras:
        if is_headline(p):
            n = add_underline_to_runs(p)
            if n:
                underlined.append((para_text(p).strip(), n))

    # Serialize preserving original declaration and existing formatting
    out = decl + "\n" + dom.documentElement.toxml()
    with open(doc_path, "w", encoding="utf-8") as f:
        f.write(out)

    print(f"Underlined {len(underlined)} headline paragraph(s):")
    for text, n in underlined:
        print(f"  - {text!r} ({n} run(s))")

    # Repack into the docx, preserving member order
    tmp = SRC + ".tmp"
    with zipfile.ZipFile(SRC) as zin, zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            if item.filename == DOC_REL:
                zout.writestr(item, out.encode("utf-8"))
            else:
                zout.writestr(item, zin.read(item.filename))
    shutil.move(tmp, SRC)
    print(f"Wrote {SRC}")


