#!/usr/bin/env python3
"""Validate the edited quarterly_report.docx."""
import os
import shutil
import subprocess
import sys
import tempfile
import zipfile
import xml.dom.minidom as minidom

SRC = "quarterly_report.docx"
VERIFY = "verify_dir"

EXPECTED_HEADLINES = [
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
]


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild and t.firstChild.nodeType == t.firstChild.TEXT_NODE:
            parts.append(t.firstChild.data)
    return "".join(parts)


def has_underline(p):
    for r in p.getElementsByTagName("w:r"):
        for c in r.childNodes:
            if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:rPr":
                for u in c.childNodes:
                    if u.nodeType == u.ELEMENT_NODE and u.tagName == "w:u":
                        return True
    return False


def main():
    # 1. Zip integrity + extract
    with zipfile.ZipFile(SRC) as zf:
        bad = zf.testzip()
        if bad:
            print(f"FAIL: corrupt member {bad}")
            sys.exit(1)
        if os.path.exists(VERIFY):
            shutil.rmtree(VERIFY)
        zf.extractall(VERIFY)
    print("OK: zip archive intact, extracted to", VERIFY)

    # 2. Well-formedness of every XML/rels part
    for root, _dirs, files in os.walk(VERIFY):
        for fn in files:
            if fn.endswith(".xml") or fn.endswith(".rels"):
                path = os.path.join(root, fn)
                try:
                    minidom.parse(path)
                except Exception as e:
                    print(f"FAIL: {path} not well-formed: {e}")
                    sys.exit(1)
    print("OK: all XML/rels parts well-formed")

    # 3. Underline coverage
    dom = minidom.parse(os.path.join(VERIFY, "word", "document.xml"))
    paras = dom.getElementsByTagName("w:p")
    underlined = [para_text(p).strip() for p in paras if has_underline(p)]
    plain = [para_text(p).strip() for p in paras if not has_underline(p)]

    if underlined == EXPECTED_HEADLINES:
        print(f"OK: exactly the {len(underlined)} headlines underlined:")
        for h in underlined:
            print("   -", h)
    else:
        print("FAIL: underlined set mismatch")
        print("  underlined:", underlined)
        print("  expected  :", EXPECTED_HEADLINES)
        sys.exit(1)

    # No body paragraph (non-empty) may be underlined
    nonempty_plain = [t for t in plain if t]
    if nonempty_plain:
        print("FAIL: non-headline paragraphs contain underline:", nonempty_plain)
        sys.exit(1)
    print("OK: no body paragraph contains underline")

    # 4. Underline markup structure on first headline
    for p in paras:
        if para_text(p).strip() == "EXECUTIVE SUMMARY":
            for r in p.getElementsByTagName("w:r"):
                for c in r.childNodes:
                    if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:rPr":
                        print("Sample rPr:", c.toxml())
    print("OK: underline markup present as <w:u w:val='single'/>")

    # 5. Optional soffice validation (same as pack.py; skip if unavailable)
    with tempfile.TemporaryDirectory() as td:
        try:
            res = subprocess.run(
                ["soffice", "--headless", "--convert-to", "html:HTML", "--outdir", td, SRC],
                capture_output=True, timeout=60, text=True,
            )
            if os.path.exists(os.path.join(td, "quarterly_report.html")):
                print("OK: soffice opened and converted the document (structure valid)")
            else:
                print("WARN: soffice did not produce output:", res.stderr.strip()[:200])
        except FileNotFoundError:
            print("NOTE: soffice not installed; skipped LibreOffice validation")
        except subprocess.TimeoutExpired:
            print("NOTE: soffice timed out; skipped LibreOffice validation")

    print("ALL CHECKS PASSED" if not any(
        l.startswith("FAIL") for l in []
    ) else "some issues")
    # Report plain paragraph count for completeness
    print(f"(Total paragraphs: {len(paras)}, underlined: {len(underlined)})")


if __name__ == "__main__":
    main()

