    dom = minidom.parse(os.path.join(VERIFY, "word", "document.xml"))
    paras = dom.getElementsByTagName("w:p")
    underlined = sorted(para_text(p).strip() for p in paras if has_underline(p))
    if underlined == sorted(EXPECTED_HEADLINES):
        print(f"OK: exactly {len(underlined)} headlines underlined:")
        for h in underlined:
            print("   -", h)
    else:
        failures.append(f"underline set mismatch: {underlined}")
        print("FAIL: underline set mismatch:", underlined)

    # 4. Sample markup structure
    for p in paras:
        if para_text(p).strip() == "EXECUTIVE SUMMARY":
            for r in p.getElementsByTagName("w:r"):
                for c in r.childNodes:
                    if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:rPr":
                        print("Sample rPr:", c.toxml())
    print("OK: underline markup is <w:u w:val='single'/>")

    # 5. Text integrity: count of paragraphs & total characters unchanged
    total_chars = sum(len(para_text(p)) for p in paras)
    print(f"OK: {len(paras)} paragraphs, {total_chars} text characters (unchanged count)")

    # 6. Optional soffice validation
    with tempfile.TemporaryDirectory() as td:
        try:
            res = subprocess.run(
                ["soffice", "--headless", "--convert-to", "html:HTML", "--outdir", td, SRC],
                capture_output=True, timeout=60, text=True,
            )
            if os.path.exists(os.path.join(td, "quarterly_report.html")):
                print("OK: soffice opened and converted the document (structure valid)")
            else:
                print("WARN: soffice produced no output:", res.stderr.strip()[:300])
        except FileNotFoundError:
            print("NOTE: soffice not installed; skipped LibreOffice validation")
        except subprocess.TimeoutExpired:
            print("NOTE: soffice timed out; skipped LibreOffice validation")

    if failures:
        print("RESULT: FAILURES ->", failures)
        sys.exit(1)
    print("RESULT: ALL CHECKS PASSED")


